(function(){
 'use strict';
 const p=s=>'<p>'+s+'</p>';
 const section=(title,...texts)=>'<section class="report-topic"><h4>'+title+'</h4>'+texts.map(p).join('')+'</section>';
 const page=(n,title,body)=>'<article class="report-page" id="report-page-'+n+'"><div class="report-kicker">온결 · 원국 상세 해설 <span>'+n+' / 20</span></div><h3>'+title+'</h3>'+body+'<div class="report-page-number">온결 개인 리포트 · '+n+' / 20</div></article>';
 const topics=[
  ['겁살','경쟁과 지켜야 할 경계',
   '겁살이라는 이름은 빼앗김과 경쟁의 이미지를 담고 있습니다. 현대적인 자기 성찰에서는 원하는 것을 얻기 위해 힘을 쓰는 방식과, 내 시간·자원을 지키는 경계를 함께 돌아보는 주제로 읽을 수 있습니다. 원국에 표시되었다고 실제로 재산을 잃거나 누군가에게 피해를 입는다는 뜻은 아닙니다.',
   '빠르게 결정을 내려야 하는 일에서는 추진력과 판단 기준이 함께 필요합니다. 다른 사람이 먼저 움직인다는 이유로 내 계획을 바꾸는지, 원래 목표를 확인한 뒤 행동하는지 살펴보세요. 경쟁 상대보다 내가 지킬 완료 기준과 감당할 수 있는 범위를 구체적으로 정하면 이 상징을 유용한 질문으로 바꿀 수 있습니다.',
   '사람들과 일할 때는 역할이 겹치는 부분을 먼저 확인해보세요. 누구의 성과로 기록되는지, 결정권은 어디에 있는지, 문제가 생기면 누가 조정하는지 불분명하면 작은 경쟁도 큰 피로가 될 수 있습니다. 겁살의 유무보다 실제 협업 구조가 중요하므로, 합의할 수 있는 내용을 문장으로 남기는 방법을 사용해보세요.',
   '시간과 자원을 사용하는 방식에서는 즉시 얻는 결과와 오래 유지할 기반을 나누어볼 수 있습니다. 새 일을 추가할 때 기존 일정에서 무엇을 줄일지까지 함께 정하면 선택의 비용이 보입니다. 신살 이름만 보고 투자나 거래를 결정하는 대신, 충분한 정보와 자신의 현실적인 조건을 기준으로 판단해야 합니다.',
   '돌아볼 질문은 “지금 내가 경쟁하는 이유는 무엇인가?”, “꼭 지켜야 하는 한계는 어디인가?”, “남의 속도 때문에 내 기준이 흔들리는가?”입니다. 최근 선택 한 가지에 이 질문을 적용하고 그때 확보한 정보와 빠져 있던 정보를 구분해보세요. 다음번에 확인할 항목이 보이면 해석이 실제 경험과 연결됩니다.'],
  ['재살','외부 요구와 대응의 기준',
   '재살은 전통 용어의 이름이 강하게 느껴지지만, 이 리포트에서는 외부 조건이 달라졌을 때 어떻게 대응하는지 돌아보는 상징으로 사용합니다. 일정 변경이나 예상 밖의 요청처럼 나의 의지만으로 정할 수 없는 상황에서 판단의 순서를 살피는 것입니다. 사고·분쟁·구속 등 특정 사건을 예고하는 표시로 사용하지 않습니다.',
   '상황 변화에 빨리 반응하는 능력은 필요한 정보를 골라내고 우선순위를 세우는 일에서 도움을 줄 수 있습니다. 다만 모든 요청을 긴급한 것으로 받아들이면 중요도가 낮은 일에도 힘을 쓰게 됩니다. 지금 처리해야 할 것, 다른 사람의 확인이 필요한 것, 다음 일정으로 옮길 것을 나누어보세요.',
   '관계에서는 부탁의 내용과 실제 책임의 범위를 구분하는 것이 핵심입니다. 상대의 사정을 이해하는 일과 그 문제를 모두 떠안는 일은 다릅니다. 요청을 받았을 때 내가 할 수 있는 부분, 할 수 없는 부분, 협의가 필요한 부분을 구체적으로 말하면 외부 압박을 줄이고 신뢰를 지키는 데 도움이 됩니다.',
   '업무에 적용한다면 변경 이력을 기록하는 방법이 유용합니다. 무엇이 언제 바뀌었고, 어떤 결과에 영향을 주며, 누가 확인해야 하는지를 짧게 남겨보세요. 처음 계획과 달라진 이유가 보이면 잘못을 추측하기보다 필요한 조정을 이야기할 수 있습니다. 이 방법은 재살이 없는 사람에게도 적용할 수 있는 일반적인 협업 습관입니다.',
   '질문은 “지금 바뀐 조건은 사실인가, 예상인가?”, “내가 즉시 대응할 범위는 어디까지인가?”, “누구와 먼저 확인해야 하는가?”입니다. 불확실한 이야기를 여러 번 생각하기보다 확인할 질문 하나를 만들어 실제 답을 구해보세요. 답을 얻은 뒤 계획을 수정하는 과정을 경험하면 대응 방식이 더 분명해집니다.'],
  ['천살','통제하기 어려운 조건과 관점의 전환',
   '천살은 이름에서 하늘이나 큰 외부 조건의 이미지를 떠올리게 합니다. 이 리포트는 그것을 피할 수 없는 벌이나 불행으로 해석하지 않습니다. 개인이 조절할 수 있는 일과 조절하기 어려운 일을 구분하고, 변화한 조건 안에서 가능한 선택을 찾아보는 성찰의 틀로 사용합니다.',
   '계획이 흔들릴 때 먼저 바뀐 사실과 나의 해석을 나누어 적어보세요. 일정이 늦어진 사실과 “앞으로 모든 일이 틀어질 것”이라는 생각은 같은 정보가 아닙니다. 확인된 조건을 기준으로 목표의 크기와 시점을 다시 정하면, 손쓸 수 없는 부분에 계속 힘을 쓰는 대신 가능한 행동을 찾을 수 있습니다.',
   '사회적인 역할에서는 전체 방향을 읽고 다른 사람의 상황을 고려하는 태도를 생각해볼 수 있습니다. 다만 큰 흐름을 이해하려는 노력 때문에 작은 실행을 미루는 경우도 있습니다. 이번 주 안에 확인할 사실 하나, 직접 바꿀 행동 하나, 기다려야 할 조건 하나를 구분하면 관점과 실행을 연결하기 쉽습니다.',
   '가까운 관계에서는 상대의 선택까지 내가 정하려고 하는지 살펴보세요. 도움이 되는 의견을 전달하되 결정할 권한은 누구에게 있는지 확인하는 것이 좋습니다. 통제의 한계를 인정하는 것은 관계를 포기하는 것과 다릅니다. 함께 정할 수 있는 약속을 구체화하고 각자의 몫을 존중하는 방식으로 접근할 수 있습니다.',
   '질문은 “내가 바꿀 수 있는 조건은 무엇인가?”, “기다리는 동안 준비할 수 있는 일은 무엇인가?”, “목표를 유지하면서 방법을 바꿀 수 있는가?”입니다. 천살이라는 이름만으로 특정 시기를 두려워하기보다 현재의 자원과 선택지를 점검하는 자료로 읽어주세요. 표에 있는 지지가 현실의 사건을 직접 일으킨다고 입증된 것은 아닙니다.'],
  ['지살','환경 변화와 새로운 경험',
   '지살은 낯선 환경과의 접촉, 활동 범위가 달라지는 모습을 돌아보는 상징으로 읽습니다. 이 리포트에서는 새로운 자리에서 어떤 정보를 먼저 모으는지, 변화에 적응할 때 무엇을 유지하는지에 초점을 둡니다. 원국에 있다고 반드시 이사를 많이 하거나 특정 직업을 선택한다는 뜻은 아닙니다.',
   '새로운 일이나 모임에 들어갈 때는 익숙한 방식이 그대로 통하지 않을 수 있습니다. 처음부터 잘해야 한다고 생각하기보다 규칙, 기대되는 역할, 도움을 구할 사람을 확인해보세요. 관찰할 시간을 따로 마련하면 낯섦을 실패로 해석하지 않고 배움의 과정으로 사용할 수 있습니다.',
   '환경을 바꾸는 선택에서는 바뀔 것과 유지할 것을 동시에 적어보세요. 활동 장소나 사람은 달라져도 일상의 리듬, 가까운 관계와의 약속, 현재 맡은 책임은 남을 수 있습니다. 변화의 장점뿐 아니라 그 과정에서 드는 시간과 준비를 함께 살피면 실제 생활에 맞는 계획을 세우기 쉽습니다.',
   '관계에서 새로운 사람을 많이 만나는 일과 신뢰를 깊게 만드는 일은 서로 다른 과정입니다. 첫 만남에서 나누는 정보와 오래 함께할 때 필요한 합의를 구분해보세요. 활동 범위가 넓어질수록 연락과 일정의 우선순위를 정하면, 모든 관계에 같은 힘을 쓰려는 부담을 줄일 수 있습니다.',
   '질문은 “이번 변화로 얻고 싶은 경험은 무엇인가?”, “처음 한 달 동안 무엇을 관찰할 것인가?”, “유지할 기반은 무엇인가?”입니다. 지살과 역마살은 서로 다른 판정 칸이므로 두 이름이 비슷하게 느껴져도 각각의 대상 지지를 확인해야 합니다. 이름의 개수를 변화의 횟수로 바꾸어 세지 않습니다.'],
  ['년살(도화)','표현과 타인의 시선',
   '년살은 십이신살 표에서 도화와 연결해 읽는 항목입니다. 여기서는 자신의 생각과 매력을 어떻게 표현하고, 주변의 반응을 어떻게 받아들이는지 살펴보는 상징으로 사용합니다. 외모, 연애 횟수, 인기의 크기나 관계 문제를 이 글자 하나로 판정하지 않습니다.',
   '말·글·이미지로 자신을 보여주는 활동에서는 전달하고 싶은 내용과 실제로 전달된 내용을 비교해볼 수 있습니다. 반응이 많다고 모든 사람이 같은 의미로 이해한 것은 아닙니다. 중요한 표현을 한 뒤 상대가 어떻게 이해했는지 확인하고 필요한 설명을 덧붙이면 표현의 완성도가 높아집니다.',
   '타인의 평가에 민감한 상황에서는 내가 중요하게 보는 기준을 먼저 정리해보세요. 좋은 반응을 얻기 위해 선택하는 것인지, 내 생각과 맞아서 선택하는 것인지 구분하는 것이 도움이 됩니다. 다른 사람에게 보이는 모습과 혼자 있을 때 필요한 시간을 함께 고려하면 표현과 휴식의 균형을 찾을 수 있습니다.',
   '가까운 관계에서 친절과 친밀함의 뜻이 다르게 받아들여질 때는 추측보다 확인이 필요합니다. 내가 제공할 수 있는 관심의 범위와 상대가 기대하는 관계를 말로 맞춰보세요. 도화라는 이름을 상대에 대한 의심이나 낙인의 근거로 사용하기보다, 관계에서 표현과 경계가 얼마나 분명한지 살피는 질문으로 활용할 수 있습니다.',
   '질문은 “나는 무엇을 보여주고 싶은가?”, “상대는 같은 의미로 받아들였는가?”, “평가와 무관하게 지키고 싶은 기준은 무엇인가?”입니다. 년살에 해당하는 지지는 선택한 삼합 기준에 따라 달라집니다. 년지 기준과 일지 기준의 결과가 다를 경우 어느 한쪽을 몰래 우선하지 않고 두 표의 근거를 함께 보여드립니다.'],
  ['월살','더딘 진행과 보이지 않는 축적',
   '월살은 진행이 선명하게 보이지 않을 때의 관찰과 준비를 돌아보는 상징으로 사용합니다. 성과가 늦게 보인다고 노력의 가치가 없어진 것은 아닙니다. 당장 확인되는 결과와 시간이 지나야 드러나는 변화를 구분하면, 현재 필요한 점검과 유지할 습관을 찾는 데 도움이 됩니다.',
   '학습이나 긴 프로젝트에서는 결과를 기다리는 동안 중간 지표를 정해보세요. 공부한 시간만이 아니라 설명할 수 있는 개념, 스스로 해결한 문제, 줄어든 오류처럼 구체적인 변화를 기록할 수 있습니다. 작은 확인 지점이 있으면 막연히 잘되고 있다거나 아무것도 안 된다고 판단하는 일을 줄일 수 있습니다.',
   '관계에서 답을 기다리는 상황에서는 확인할 수 있는 정보와 추측을 구분해보세요. 답이 늦는 이유를 혼자 결론 내리기보다 언제까지 어떤 답이 필요한지 전달하는 편이 좋습니다. 나의 일정과 상대의 여건을 함께 확인하면 기다림이 일방적인 부담이 되는 것을 줄일 수 있습니다.',
   '스스로 준비하는 시간은 외부에 보이는 활동보다 덜 중요하게 느껴질 수 있습니다. 그러나 자료를 정리하고 방법을 다듬는 과정도 결과의 일부입니다. 준비가 실행을 미루는 핑계가 되는지, 실제로 다음 단계의 품질을 높이는지 구분하려면 작은 시험 결과를 만들어 비교하는 방법이 유용합니다.',
   '질문은 “지금 확인 가능한 변화는 무엇인가?”, “더 준비해야 할 것과 시작해도 될 것은 무엇인가?”, “언제 다시 판단할 것인가?”입니다. 월살의 표시는 긴 침체나 고립을 예고하지 않습니다. 눈에 보이는 결과가 적은 시기에 어떤 기준으로 진행을 확인할지 생각하는 참고 항목으로 읽어주세요.'],
  ['망신살','드러나는 역할과 말의 책임',
   '망신살이라는 이름을 문자 그대로 미래의 수치나 평판 손상으로 받아들이지 마세요. 이 리포트에서는 자신이 드러나는 자리에서 표현, 설명, 책임을 어떻게 연결하는지 돌아보는 항목으로 사용합니다. 보이지 않던 의견과 행동이 공개될 때 준비가 필요한 부분을 살펴보는 것입니다.',
   '회의나 발표에서는 사실과 의견을 구분하여 말하는 방법이 도움이 됩니다. 확인한 내용, 아직 확인 중인 내용, 제안하는 방향을 따로 설명하면 상대가 판단할 근거를 얻습니다. 강한 표현으로 관심을 끄는 것보다 내가 책임질 수 있는 범위 안에서 정확하게 전달하는 경험을 쌓아보세요.',
   '온라인 표현에서는 올리기 전후의 맥락이 달라질 수 있습니다. 특정 사람에게만 통하는 농담이나 생략된 설명이 다른 사람에게도 같은 뜻으로 전달되는지 확인해보세요. 표현을 지나치게 두려워할 필요는 없지만, 공개 범위와 정보의 정확성을 한 번 더 살피면 불필요한 오해를 줄일 수 있습니다.',
   '실수를 발견했을 때는 원인 설명과 수정 행동을 함께 제시해보세요. 변명처럼 들릴까 봐 아무 말도 하지 않거나, 모든 책임을 혼자 떠안는 방식 대신 확인된 사실과 고칠 부분을 분명하게 말할 수 있습니다. 신뢰는 실수가 한 번도 없는 모습만이 아니라, 문제를 다루는 태도에서도 만들어집니다.',
   '질문은 “내 말에서 확인된 사실은 무엇인가?”, “듣는 사람에게 필요한 맥락은 충분한가?”, “오류가 있으면 어떻게 바로잡을 것인가?”입니다. 원국에서 같은 망신살 대상 지지가 여러 위치에 있어도 평판 문제가 여러 번 발생한다고 세지 않습니다. 표시 위치는 해석의 출발점이며 실제 사건의 목록이 아닙니다.'],
  ['장성살','주도권과 역할의 중심',
   '장성살은 중심을 잡고 역할을 이끄는 이미지를 돌아보는 항목입니다. 이 리포트에서는 내 기준을 제시하는 방식, 책임을 맡는 방식, 다른 사람의 의견을 받아들이는 방식을 함께 살펴봅니다. 해당한다고 반드시 리더가 되거나 권한을 얻는다는 뜻은 아니며, 해당하지 않아도 주도적인 역할을 수행할 수 있습니다.',
   '주도권은 결정을 혼자 내리는 것과 항상 같지 않습니다. 일을 이끌 때는 목표를 공유하고, 결정이 필요한 지점을 구분하며, 구성원이 자기 역할을 이해하도록 돕는 과정이 필요합니다. 내가 직접 할 일과 다른 사람에게 맡길 일을 나누면 책임감이 과도한 통제로 바뀌는 것을 줄일 수 있습니다.',
   '자신의 기준이 분명할수록 다른 관점을 받아들이는 방법도 준비해보세요. 반대 의견을 들었을 때 핵심 목표를 흔드는 내용인지, 방법을 개선하는 내용인지 구분할 수 있습니다. 반드시 지켜야 할 기준과 조정 가능한 부분을 나누어 설명하면 결정의 일관성과 협업의 유연성을 함께 유지할 수 있습니다.',
   '가까운 관계에서는 내가 좋은 의도로 내린 결정이 상대에게도 필요한지 확인하는 일이 중요합니다. 해결책을 제시하기 전에 지금 상대가 원하는 것이 조언인지, 도움이 필요한 일인지, 이야기를 들어주는 것인지 물어보세요. 역할의 중심을 잡는 것과 상대의 선택을 존중하는 것을 함께 연습할 수 있습니다.',
   '질문은 “이 일의 책임 범위는 어디까지인가?”, “내가 없어도 진행되도록 무엇을 공유해야 하는가?”, “누구의 의견이 빠져 있는가?”입니다. 장성살은 십이신살에서 기준 그룹의 중심 지지에 배정됩니다. 일지 자체가 이 이름으로 표시될 수 있지만, 그것을 사회적 지위의 보장으로 해석하지 않습니다.'],
  ['반안살','축적된 기반과 활용의 방식',
   '반안살은 이미 갖춘 기반을 어떻게 활용하고 다음 단계로 연결하는지 돌아보는 상징으로 사용합니다. 익숙한 기술, 경험, 관계를 이용해 안정적으로 진행하는 모습을 생각해볼 수 있습니다. 표에 있다고 승진이나 성공이 보장되는 것은 아니며, 없다고 축적의 기회가 사라지는 것도 아닙니다.',
   '지금 가진 기반을 구체적으로 적어보세요. 오래 해본 작업, 설명할 수 있는 지식, 도움을 주고받을 수 있는 관계, 이미 만들어둔 자료가 포함될 수 있습니다. 막연히 준비가 부족하다고 느끼는 대신 실제 사용할 수 있는 것이 무엇인지 확인하면 새로운 과제의 시작점이 더 분명해집니다.',
   '익숙한 방법이 안정감을 주더라도 새로운 조건에서는 점검이 필요합니다. 예전에는 잘 맞았던 역할 분담이나 일정이 지금도 유효한지 확인해보세요. 기존 경험을 버리기보다 핵심 원리와 상황에 따른 세부 방법을 나누면, 축적한 것을 유지하면서 필요한 변화도 받아들일 수 있습니다.',
   '도움을 받은 경험이 있다면 그것을 다음 협업에서 어떻게 활용할지 생각해보세요. 연락만 유지하는 관계와 실제로 정보를 공유할 수 있는 관계는 다를 수 있습니다. 상대의 도움을 당연하게 여기기보다 내가 제공할 수 있는 경험과 결과를 함께 나누면 기반이 일방적인 의존으로 바뀌는 것을 줄일 수 있습니다.',
   '질문은 “이미 갖춘 것 중 지금 쓸 수 있는 것은 무엇인가?”, “유지할 방법과 바꿀 방법은 무엇인가?”, “축적한 경험을 누구와 나눌 수 있는가?”입니다. 반안이라는 이름만으로 어떤 방향이나 시기가 반드시 유리하다고 정하지 않습니다. 지금의 조건에서 실제로 활용할 수 있는 기반을 살펴보는 데 초점을 두세요.'],
  ['역마살','이동성과 변화의 목적',
   '역마살은 활동 범위를 넓히고 새로운 조건을 찾아 움직이는 이미지를 돌아보는 항목입니다. 이동은 물리적인 장소의 변화뿐 아니라 업무 방식, 학습 분야, 만나는 사람의 범위가 달라지는 경험으로 생각해볼 수 있습니다. 원국에 있다고 해외 생활이나 이직이 정해져 있는 것은 아닙니다.',
   '변화를 계획할 때는 움직이는 것 자체와 그 목적을 구분해보세요. 새로운 장소나 역할에서 얻고 싶은 경험이 무엇인지, 현재 환경에서 그 경험을 일부 시험해볼 수 있는지 확인하는 것이 좋습니다. 큰 결정을 한 번에 내리기 전에 짧은 체험이나 작은 과제로 적합성을 살피는 방법을 사용할 수 있습니다.',
   '활동이 많아질수록 새로운 경험을 정리하는 시간이 필요합니다. 만난 사람, 배운 내용, 다음 행동을 간단히 기록하면 경험이 흩어지지 않습니다. 바쁘게 움직인 하루와 중요한 과제가 진전된 하루가 같은 것은 아니므로, 이동과 활동의 횟수보다 목표와 연결된 결과를 확인해보세요.',
   '관계에서는 변화하는 일정 속에서 유지할 약속을 정해보세요. 자주 연락하는 방식이 어려워지더라도 미리 일정과 필요를 설명하면 서로의 기대를 조정할 수 있습니다. 새로운 관계가 늘어날 때 기존의 중요한 관계를 어떻게 이어갈지 함께 생각하면 활동 범위와 신뢰를 균형 있게 다룰 수 있습니다.',
   '질문은 “이번 변화가 해결하려는 문제는 무엇인가?”, “돌아왔을 때 남을 경험은 무엇인가?”, “유지할 생활의 기반은 무엇인가?”입니다. 지살과 역마살은 비슷한 이동의 상징으로 설명되기도 하지만 같은 표의 서로 다른 지지 칸에 배정됩니다. 두 항목을 중복하여 이동 사건의 횟수처럼 계산하지 않습니다.'],
  ['육해살','작은 부담과 지속적인 점검',
   '십이신살의 육해살은 긴 과정에서 생기는 부담과 세부 점검을 돌아보는 항목으로 사용합니다. 여기서 “육해살”이라는 신살 이름과 두 지지 사이의 관계인 “해(육해)”는 계산법이 다른 개념입니다. 신살 표에 해당하는 것만으로 원국에 특정 해 관계가 있다고 판단하지 않습니다.',
   '큰 계획은 분명한데 작은 불편이 계속 쌓이는 상황을 떠올려보세요. 반복되는 확인 요청, 맞지 않는 일정, 담당자가 정해지지 않은 일이 전체 진행을 방해할 수 있습니다. 불편을 막연한 느낌으로 남기기보다 언제 무엇이 반복되는지 기록하면 바꿀 수 있는 지점이 보입니다.',
   '업무에서는 작은 확인 항목을 일정에 포함하는 방식이 도움이 됩니다. 처음 합의한 기준이 여전히 유효한지, 놓친 자료는 없는지, 전달할 대상이 빠지지 않았는지 점검해보세요. 모든 일을 다시 검사하려고 하기보다 반복해서 문제가 된 항목부터 정리하면 점검에 드는 부담도 줄일 수 있습니다.',
   '관계에서 상대를 배려하느라 말하지 않은 요구가 있는지 살펴보세요. 상대가 알아주기를 기다리는 방식은 서로 다른 추측을 만들 수 있습니다. 필요한 시간, 연락 방식, 함께 할 수 있는 일을 구체적으로 말하면 작은 부담이 오래 누적되는 것을 줄이는 데 도움이 됩니다.',
   '질문은 “반복해서 생기는 작은 불편은 무엇인가?”, “말하지 않은 필요가 있는가?”, “짧은 점검으로 예방할 수 있는 일은 무엇인가?”입니다. 이 항목은 배신, 질병, 불행 같은 사건의 예고로 사용하지 않습니다. 현재 생활에서 이미 관찰되는 상황을 기준으로 설명과 실제 경험이 연결되는지 확인해주세요.'],
  ['화개살','몰입과 정리, 내적인 관심',
   '화개살은 관심을 안으로 모아 탐구하고 정리하는 모습을 돌아보는 항목입니다. 읽기, 연구, 창작처럼 혼자 깊이 생각하는 활동과 연결해 질문할 수 있습니다. 이 글자가 있다고 외롭거나 가족과 떨어져 살아야 한다고 판정하지 않으며, 없다고 몰입과 창작의 능력이 없는 것도 아닙니다.',
   '관심 있는 주제를 오래 파고들 때는 배우는 일과 결과를 만드는 일을 연결해보세요. 계속 자료를 모으는 과정에서 무엇을 이해했고 어떤 질문이 남았는지 짧게 정리하면 탐구의 방향이 보입니다. 결과를 다른 사람에게 설명할 수 있는 형태로 만들면 생각의 정확성도 확인할 수 있습니다.',
   '혼자 있는 시간은 개인에게 필요한 집중과 회복의 조건이 될 수 있습니다. 다만 그 시간이 필요한 이유를 주변에 설명하지 않으면 거리감으로 받아들여질 수 있습니다. 집중할 시간과 함께할 시간을 미리 이야기하면 나의 리듬을 유지하면서 관계의 기대도 맞출 수 있습니다.',
   '창작이나 연구에서는 완성도를 높이는 과정과 공유할 시점을 함께 정해보세요. 더 생각할 내용이 남았더라도 중간 결과를 보여주면 다른 관점의 도움을 받을 수 있습니다. 자신의 기준만으로 계속 다듬는 일과 실제 전달력을 확인하는 일을 번갈아 하면 몰입의 결과를 생활에 연결하기 쉽습니다.',
   '질문은 “내가 오래 관심을 두는 주제는 무엇인가?”, “혼자 생각한 내용을 어떻게 표현할 것인가?”, “집중과 교류의 시간을 어떻게 나눌 것인가?”입니다. 화개살은 기준 삼합 그룹의 마지막 지지에 배정됩니다. 기준이 년지인지 일지인지에 따라 대상이 달라질 수 있으므로 결과의 이름보다 판정 근거를 먼저 확인하세요.']
 ];
 const positional={연주:'연주에서는 처음 접한 환경과 사회적 배경을 돌아보는 질문으로 읽습니다. 가족의 성격이나 어린 시절 사건을 지지 하나로 추정하지 않고, 내가 익숙하게 받아들여온 기준과 실제 경험을 비교해보세요.',월주:'월주에서는 반복되는 업무 방식과 사회적 역할에 연결해 생각합니다. 어떤 환경에서 이 주제가 잘 드러나는지, 역할을 맡을 때 필요한 조건은 무엇인지 확인하면 자신의 일하는 방식을 구체화할 수 있습니다.',일주:'일주에서는 자신의 선택 기준과 가까운 관계에서의 경험을 함께 살핍니다. 상대의 성격이나 관계의 결말을 정하는 표시로 사용하지 않고, 내가 편안하게 느끼는 방식과 실제 대화의 차이를 돌아보세요.',시주:'시주에서는 개인적인 구상과 오래 이어가고 싶은 관심을 돌아보는 단서로 읽습니다. 자녀의 운명이나 노년의 사건을 예측하지 않으며, 앞으로 만들고 싶은 생활과 현재의 작은 실천을 연결해보세요.'};
 function twelvePages(r,input){
  return topics.map((t,i)=>{
   const day=r.twelveDay[i],year=r.twelveYear[i];
   const outcome='<div class="report-verdict"><strong>일지 기준: '+day.status+'</strong><span>기준 '+day.base+' · '+day.group+' 그룹 → 대상 '+day.target+'</span><span>해당 위치: '+(day.positions.join(' · ')||'현재 확인된 위치 없음')+'</span><strong>년지 기준: '+year.status+'</strong><span>기준 '+year.base+' · '+year.group+' 그룹 → 대상 '+year.target+'</span><span>해당 위치: '+(year.positions.join(' · ')||'현재 확인된 위치 없음')+'</span></div>';
   const table='<div class="report-table-wrap"><table class="report-table"><thead><tr><th>원국 위치</th><th>지지</th><th>일지 기준</th><th>년지 기준</th></tr></thead><tbody>'+r.pillars.map(v=>'<tr><td>'+v.label+'</td><td>'+(v.unknown?'미상':v.zhi)+'</td><td>'+(v.unknown?'판정 보류':v.zhi===day.target?'해당':'해당 없음')+'</td><td>'+(v.unknown?'판정 보류':v.zhi===year.target?'해당':'해당 없음')+'</td></tr>').join('')+'</tbody></table></div>';
   const hits=[...new Map([...day.hits,...year.hits].map(v=>[v.label,v])).values()];
   const locations=hits.length?hits.map(v=>section(v.label+' '+v.zhi+'에서 읽는 관점',positional[v.label])).join(''):section('원국에 표시되지 않은 경우',
    '이 항목은 알려진 원국 글자에서 조건에 해당하는 지지를 찾지 못한 결과입니다. 신살 표의 미해당은 관련 경험이나 능력이 없다는 뜻이 아닙니다. 아래 설명은 이 이름의 일반적인 상징을 이해하기 위한 해설이며, 당신에게 그 성향이 있다고 판정한 문장이 아닙니다. 시간 미상이라면 시주에 대한 유무는 아직 확인할 수 없습니다.');
   const years=r.years.map(y=>y.year+'년 '+y.ganZhi[1]+': '+(y.ganZhi[1]===day.target?'일지 기준 해당':y.ganZhi[1]===year.target?'년지 기준 해당':'두 기준에서 미해당')).join(' / ');
   const linked=r.branchRelations.found.filter(f=>f.members.some(v=>hits.some(h=>h.label===v.label)));
   return page(i+4,t[0]+' — '+t[1],outcome+table+
    section('어떤 기준으로 포함되는가','당신의 일지 '+day.base+'가 속한 '+day.group+' 삼합 그룹에서 '+t[0]+'의 대상은 '+day.target+'입니다. 년지 '+year.base+'가 속한 '+year.group+' 그룹에서는 '+year.target+'입니다. 기준과 원국의 연·월·일·시 지지를 각각 대조하며 기준 위치 자체도 검사에 포함합니다. 두 기준의 결과를 합쳐서 새로운 신살 개수로 계산하지 않습니다.',
      day.target===year.target?'년지와 일지가 같은 삼합 그룹이므로 이 항목의 대상 지지가 같습니다. 두 표에서 같은 위치가 표시되어도 서로 독립된 사건 두 개를 뜻하지 않습니다. 같은 규칙이 같은 글자를 다시 확인한 결과로 이해하면 됩니다.':'년지와 일지가 서로 다른 삼합 그룹이므로 같은 원국 글자도 기준에 따라 다른 신살 이름이 붙을 수 있습니다. 이 차이는 오류가 아니라 출발점의 차이입니다. 리포트에서는 일지 기준을 앞에 두고 년지 기준을 비교 자료로 함께 제공합니다.')+
    section('이 이름을 해석하는 범위',t[2])+locations+section('일과 활동에서 읽기',t[3])+section('사람과의 관계에서 읽기',t[4])+section('생활에서 활용하는 방법',t[5])+
    section('원국 관계와 운의 글자를 함께 확인하기',
      linked.length?'이 항목이 표시된 위치에는 '+linked.map(f=>f.label+' '+f.kind).join('; ')+' 관계도 함께 보입니다. 신살과 지지 관계는 서로 다른 판정이므로 한 글자에 겹쳐 표시될 수 있습니다. 그 사실만으로 영향이 몇 배 커진다고 판단하지 않고, 연결된 위치와 관계의 종류를 다음 지지 해설에서 함께 살펴봅니다.':'이 항목이 표시된 위치와 연결되는 추가 지지 관계는 현재 검사 범위에서 확인되지 않았습니다. 이는 신살이 작용하지 않거나 강하지 않다는 판정이 아닙니다. 신살의 유무와 지지 관계의 유무는 별도로 표시하고, 전체 구조를 단순한 점수로 합산하지 않습니다.',
      '앞으로 3년의 연도 지지 대조는 '+years+'입니다. 이것은 연도 글자가 해당 신살 칸과 일치하는지 비교한 것이며, 원국에 없던 글자가 출생 원국에 추가되었다는 뜻은 아닙니다. 같은 이름이 운에서 보이더라도 사건을 확정하거나 날짜를 지정하지 않습니다.')+
    section('나에게 적용할 질문',t[6]));
  }).join('');
 }
 const meanings={
  충:['서로 마주하는 두 지지의 관계','같은 시점에 서로 다른 방향의 요구가 나타나는 장면을 돌아보는 관점입니다. 바꾸려는 선택과 유지하려는 기반을 각각 적고, 어느 조건에서 무엇을 우선할지 구체적으로 정리해보세요.'],
  육합:['두 지지가 짝을 이루는 관계','역할과 관심이 연결되는 상황을 돌아볼 수 있습니다. 합의한 목표가 같은지, 각자 맡은 일이 분명한지, 기대가 달라질 때 어떻게 조정할지 확인하면 협력의 조건이 더 잘 보입니다.'],
  파:['두 지지의 특정 짝을 가리키는 관계','기존 방식의 틈과 수정할 부분을 살피는 관점으로 읽습니다. 계획이나 약속을 모두 버리기보다 무엇이 실제로 맞지 않는지 확인하고 작은 수정으로 해결되는 부분부터 나누어보세요.'],
  해:['두 지지의 특정 짝을 가리키는 관계','말하지 않은 기대나 조율되지 않은 필요를 돌아보는 관점으로 사용합니다. 상대가 내 의도를 알아줄 것이라고 가정하기보다 구체적인 요청과 가능한 범위를 서로 확인해보세요.'],
  자묘형:['子와 卯의 형 관계','서로 다른 표현과 기준이 어긋나는 장면을 돌아보세요. 말의 내용과 전달 방식, 상황의 맥락을 나누어 확인하면 어느 부분에서 오해가 생겼는지 구체적으로 이야기할 수 있습니다.'],
  '형(두 지지)':['삼형 그룹에서 서로 다른 두 글자를 확인한 상태','같은 문제를 서로 다른 방식으로 해결하려는 장면을 돌아볼 수 있습니다. 두 글자만 확인했으므로 세 글자가 모두 갖추어진 삼형 완비와 구분하며, 규칙과 역할을 명시하는 질문으로 읽습니다.'],
  자형:['辰·午·酉·亥 중 같은 지지가 두 위치 이상 반복된 상태','같은 기준을 반복해서 확인하는 상황과 점검이 과해지는 상황을 나누어보세요. 자형이라는 이름을 스스로를 해치거나 질병이 생긴다는 뜻으로 사용하지 않습니다.'],
  '동지 반복':['같은 지지가 서로 다른 기둥에 반복된 상태','반복된 글자가 어디에 있는지 먼저 확인해보세요. 같은 지지라도 천간과 주변 글자가 다르므로 두 기둥 전체가 같지는 않습니다. 반복을 장점이나 문제의 크기로 곧바로 환산하지 않습니다.']
 };
 function pairExplanation(item){
  const {a,b}=item;
  return section(item.label+' — '+(item.kinds.join(' · ')||'검사한 쌍 관계 없음'),
   a.label+'는 '+window.OngyeolRelations.role[a.label]+', '+b.label+'는 '+window.OngyeolRelations.role[b.label]+'을 돌아보는 위치입니다. '+(item.adjacent?'두 위치는 원국에서 이웃합니다.':'두 위치 사이에는 다른 기둥이 놓여 있습니다.')+' 이웃 여부는 위치 정보이며 영향력의 크기를 자동으로 정한 점수는 아닙니다.',
   item.kinds.length?item.kinds.map(k=>{const m=meanings[k];return k+'은 '+m[0]+'입니다. '+m[1];}).join(' '):'이 지지 쌍은 육합·충·형·파·해·자형·동지 반복의 현재 규칙에 해당하지 않습니다. 그렇다고 두 위치가 현실에서 무관하다는 뜻은 아닙니다. 아래 그룹 관계에서는 삼합·방합의 구성원인지 따로 확인합니다. 두 글자의 조합만으로 원국 전체를 평가하지 않습니다.');
 }
 function relationships(r){
  const rel=r.branchRelations;
  const rows=rel.pairs.map(v=>'<tr><td>'+v.label+'</td><td>'+(v.adjacent?'이웃':'떨어짐')+'</td><td>'+(v.kinds.join(' · ')||'해당 없음')+'</td></tr>').join('');
  const table='<div class="report-table-wrap"><table class="report-table"><thead><tr><th>대조한 지지 위치</th><th>배치</th><th>관계</th></tr></thead><tbody>'+rows+'</tbody></table></div>';
  const summary=['충','육합','형(두 지지)','삼형 완비','자묘형','자형','파','해','삼합','반합','방합','방합 일부'].map(k=>{const hits=rel.found.filter(f=>f.kind===k);return '<li><strong>'+k+'</strong> '+(hits.length?hits.map(h=>h.label).join('; '):'확인된 글자에서 해당 없음')+'</li>';}).join('');
  const a=page(16,'원국의 충과 육합 — 위치별 관계 지도',
    p('원국에서 확인한 지지는 '+r.pillars.map(v=>v.label+' '+(v.unknown?'미상':v.zhi)).join(' · ')+'입니다. 서로 다른 두 위치를 빠짐없이 짝지어 '+rel.pairs.length+'개의 쌍을 검사했습니다. 같은 쌍에 여러 관계가 성립하면 모두 표시하며, 합이 있다는 이유로 파나 형을 지우지 않습니다.')+table+'<ul class="report-relation-list">'+summary+'</ul>'+
    section('충은 어떤 조건에서 표시되는가','육충의 짝은 子午·丑未·寅申·卯酉·辰戌·巳亥입니다. 두 위치의 지지가 이 짝 중 하나일 때 충으로 표시합니다. 충은 지지 사이의 관계 이름이며, 충이 있다는 사실만으로 충돌·이별·사고 같은 사건이 정해지는 것은 아닙니다. 어느 위치가 연결되고 다른 관계가 겹치는지 확인한 다음 해석해야 합니다.',
      rel.found.some(f=>f.kind==='충')?'당신의 원국에서 확인된 충은 '+rel.found.filter(f=>f.kind==='충').map(f=>f.label).join('; ')+'입니다. 이 관계에 연결된 위치의 생활 주제를 따로 적어보세요. 외부 요구와 나의 기준, 오래 유지한 방식과 바꾸고 싶은 방식처럼 서로 다른 조건을 구체화하면 조정할 수 있는 선택이 보일 수 있습니다.':'현재 확인한 지지 쌍에는 육충이 없습니다. 충이 없다고 변화나 의견 차이가 없는 삶이라고 볼 수는 없습니다. 원국에 충이 없는 결과와 실제 경험의 변화는 서로 다른 종류의 정보입니다. 향후 운의 지지와의 대조는 20장의 연도별 부분에서 따로 보여드립니다.')+
    section('육합과 합화는 같은 판정이 아니다','육합의 짝은 子丑·寅亥·卯戌·辰酉·巳申·午未입니다. 여기서는 짝이 있는지만 검사하며, 두 글자가 특정 오행으로 완전히 바뀌는 합화 성립을 판정하지 않습니다. 계절·주변 글자·다른 관계 등의 조건을 검토하지 않고 표면 오행 개수를 바꾸지 않습니다.',
      '합은 무조건 좋은 관계, 충은 무조건 나쁜 관계라는 식으로 읽지 마세요. 협력이 도움이 되는 상황도 있고 합의가 필요한 방향 전환을 늦추는 상황도 있습니다. 반대로 의견 차이가 개선의 계기가 되기도 합니다. 관계 이름을 평가 점수로 사용하기보다 어떤 요구가 연결되어 있는지 묻는 방식으로 읽어주세요.')+
    section('결과를 읽는 순서','먼저 대상 글자 두 개를 확인하고, 다음으로 원국 위치와 이웃 여부를 확인합니다. 같은 쌍에 표시된 모든 이름을 읽은 뒤 삼합·방합 같은 그룹 관계를 살펴보세요. 시간 미상일 때는 시주와의 관계를 검사할 수 없으므로, 현재의 미해당을 원국 전체의 확정적인 부재로 해석하지 않습니다.'));
  const b=page(17,'형·파·해·자형 — 겹치는 관계의 해설',
    section('형의 두 글자와 세 글자를 구분하기','형은 子卯, 寅巳申, 丑戌未의 구성을 구분해 표시합니다. 이 리포트는 寅巳申 또는 丑戌未 중 서로 다른 두 글자가 있으면 “형(두 지지)”로, 세 글자가 모두 있으면 “삼형 완비”로 따로 표시합니다. 두 글자만으로 삼형이 완전히 갖추어졌다고 쓰지 않으며, 어떤 형 규칙을 적용했는지 결과에 드러냅니다.',
      '형의 판정 방식에는 관례 차이가 있습니다. 다른 서비스가 두 글자 형을 표시하지 않거나 방향을 따로 구분할 수 있습니다. 여기서는 구성원 두 글자의 동시 존재를 검사하는 방식을 사용합니다. 결과를 비교할 때는 글자 자체뿐 아니라 어떤 기준을 사용했는지 함께 확인해야 합니다.')+
    section('파와 해의 대조표','파의 짝은 子酉·丑辰·寅亥·卯午·巳申·未戌입니다. 해의 짝은 子未·丑午·寅巳·卯辰·申亥·酉戌입니다. 표의 짝이 보일 때 해당 위치를 표시합니다. 寅亥와 巳申은 육합과 파에 동시에 해당하므로, 한 이름만 남기는 방식은 원국 관계의 일부를 빠뜨릴 수 있습니다.',
      '육해살은 십이신살 표에서 한 기준 그룹에 배정된 신살이고, 지지의 해는 원국 두 지지가 특정 짝을 이루는 관계입니다. 이름이 비슷해도 계산 과정이 다릅니다. 육해살이 없는데 해가 보일 수 있고, 육해살이 있는데 해의 짝이 없을 수도 있으므로 서로 대체해서 해석하지 않습니다.')+
    section('자형과 동지 반복의 차이','자형은 辰辰·午午·酉酉·亥亥처럼 지정한 지지가 서로 다른 위치에 반복될 때 표시합니다. 다른 지지가 반복되면 “동지 반복”만 표시합니다. 같은 글자가 두 개 있다고 모두 자형으로 이름 붙이지 않습니다. 또 지지가 같아도 해당 천간과 위치가 다르면 기둥 전체는 다른 구성입니다.')+
    rel.pairs.filter(v=>v.kinds.some(k=>!['충','육합'].includes(k))).map(pairExplanation).join('')+
    section('겹치는 이름을 하나의 사건으로 바꾸지 않기','한 쌍에 육합과 파, 형과 해 등이 겹칠 수 있습니다. 이 이름들은 서로 다른 분류표에서 같은 글자를 본 결과이며, 별도의 사건이 그 수만큼 발생한다는 뜻이 아닙니다. 관계를 읽을 때는 “연결하려는 요구가 무엇인가”, “조정할 기준이 무엇인가”처럼 실제 경험에서 확인 가능한 질문을 사용하세요.',
      '현재 표시된 관계가 없다면 해당 규칙에 맞는 글자가 없다는 의미입니다. 설명의 일반적인 주제를 당신의 고정된 성향으로 받아들이지 마세요. 반대로 표시된 관계가 있더라도 실제 생활에서 관련 경험이 없다면 억지로 과거 사건을 끼워 맞출 필요가 없습니다. 기록된 조건과 자신의 경험을 나누어 읽는 것이 좋습니다.')+
    section('관계에서 시도할 수 있는 조정','의견 차이가 생겼을 때는 사실, 각자의 필요, 합의할 수 있는 기준을 순서대로 이야기해보세요. 서로의 의도를 추측하는 대신 같은 정보를 보고 있는지 확인하고, 함께 결정할 영역과 각자 결정할 영역을 구분합니다. 이러한 대화 방법은 형·파·해의 유무와 관계없이 적용할 수 있는 생활상의 제안입니다.'));
  const groupInfo=[['삼합',['申子辰','寅午戌','巳酉丑','亥卯未']],['방합',['寅卯辰','巳午未','申酉戌','亥子丑']]].map(([kind,sets])=>section(kind+' 구성 점검',sets.map(set=>{const present=[...set].filter(z=>r.pillars.some(v=>!v.unknown&&v.zhi===z)),missing=[...set].filter(z=>!present.includes(z));return set+': 확인 '+(present.join('·')||'없음')+' / '+(missing.length?'부족 '+missing.join('·'):'세 글자 완비')+'.';}).join(' '))).join('');
  const c=page(18,'삼합·반합·방합과 여섯 위치의 종합 해설',
    section('세 글자의 구조를 따로 보는 이유','삼합은 申子辰·寅午戌·巳酉丑·亥卯未의 세 글자 구성입니다. 방합은 寅卯辰·巳午未·申酉戌·亥子丑의 계절 그룹입니다. 원국에 구성원 세 글자가 모두 있으면 완비로 표시하지만, 자동으로 합화한다고 판단하거나 원래 오행 집계를 바꾸지는 않습니다.')+groupInfo+
    section('반합과 일부 구성의 표시','삼합 그룹 중 두 글자만 있을 때는 그룹의 중심 지지인 子·午·酉·卯를 포함한 경우에만 “반합”으로 표시합니다. 중심 지지를 제외한 두 글자만 있는 경우는 현재 규칙에서 반합으로 이름 붙이지 않습니다. 방합에서 두 구성원만 확인하면 “방합 일부”로 표시하고 빠진 글자도 함께 알려드립니다.',
      rel.found.filter(f=>['삼합','반합','방합','방합 일부','삼형 완비'].includes(f.kind)).map(f=>f.kind+' '+f.set+': '+f.label+(f.missing&&f.missing.length?' / 부족 '+f.missing.join('·'):'')+' / 연결 오행 '+(f.element||'해당 없음')+'.').join(' ')||'현재 확인된 원국에서는 표시 규칙에 맞는 완비 그룹이나 반합을 찾지 못했습니다. 시간 미상일 때는 빠진 시주가 구성원일 가능성을 별도로 남겨두어야 합니다.')+
    rel.pairs.map(pairExplanation).join('')+
    section('원국에서 연결을 읽는 실제 순서','같은 글자가 여러 기둥에 있으면 어떤 위치가 서로 연결되는지 구분해서 읽어보세요. 연주와 월주의 관계는 익숙한 배경과 사회 활동의 접점을, 월주와 일주의 관계는 사회 역할과 자신의 기준의 접점을 돌아보는 질문으로 사용할 수 있습니다. 이 위치 해석을 특정 가족의 행동이나 인생 사건으로 확정하지 않습니다.'));
  return a+b+c;
 }
 function concluding(r,input){
  const noble=r.sinsal.find(s=>s.name==='천을귀인');
  const hidden=r.pillars.filter(v=>!v.unknown).map(v=>section(v.label+' '+v.zhi+'의 지장간',
   '라이브러리의 지장간 목록은 '+v.hiddenStems.map(h=>h.gan+'('+h.element+' / '+h.relation+')').join(' · ')+'입니다. 지지는 대표 오행 하나로 표시되지만 내부 구성은 이렇게 여러 천간으로 표현하기도 합니다. 표면 글자 수 집계와는 별도로, 첫 화면의 가중 오행·통근·득세 참고 계산에 이 목록을 사용합니다. 월지의 가중치를 높이며 사용한 계수와 신강약 지표의 계산 방식은 첫 화면에서 펼쳐볼 수 있습니다.')).join('');
  const years=r.years.map(y=>{
   const incoming={label:y.year+'년 세운',zhi:y.ganZhi[1],gan:y.ganZhi[0]};
   const interactions=r.pillars.filter(v=>!v.unknown).flatMap(v=>window.OngyeolRelations.analyze([v,incoming]).found.filter(f=>!['방합 일부','반합'].includes(f.kind)).map(f=>f.label+' '+f.kind));
   return section(y.year+'년 '+y.ganZhi+'와 원국의 대조',
    interactions.length?'세운 지지 '+incoming.zhi+'와 알려진 원국 지지를 대조하면 '+interactions.join('; ')+'가 확인됩니다. 이 표시는 원국 내부의 관계와 구분한 운의 글자 대조입니다. 해의 지지가 어떤 위치와 연결되는지 보여주며, 충이 생기는 해에 특정 사건이 반드시 발생한다고 판단하지 않습니다.':'세운 지지 '+incoming.zhi+'와 알려진 원국 사이에서 현재 쌍 관계 규칙에 맞는 항목은 없습니다. 운의 글자는 원국의 글자를 바꾸지 않습니다. 관계가 없다는 결과는 그 해에 아무 변화가 없거나 특별히 평온하다는 예측을 의미하지 않습니다.');
  }).join('');
  return page(20,'지장간·추가 귀인·세운 관계와 읽기 가이드',
   section('십이신살 외의 천을귀인',
    '일간 '+r.day+' 기준 천을귀인 대상 지지는 '+noble.target+'이고, 해당 위치는 '+(noble.positions.join(' · ')||'알려진 원국에서 없음')+'입니다. 천을귀인은 십이신살의 12개 분류에 포함되는 항목이 아니라 별도 규칙으로 계산한 귀인입니다. 표에 넣어 총 13신살처럼 이름 붙이지 않고 구분해서 제공합니다.',
    '도움의 상징을 생활에 연결한다면 지금 맡은 일에서 필요한 정보와 조언을 누구에게 요청할지 정리해볼 수 있습니다. 해당 여부만으로 실제 후원자나 도움의 시기를 예측하지 않습니다. 도움을 받는 일과 경험을 나누는 일을 함께 생각하면 단순히 좋은 이름이 있다고 기다리는 방식보다 구체적인 활용이 가능합니다.')+hidden+years+
   section('전체 리포트를 읽는 순서',
    '먼저 1~3장에서 일간과 표면 오행, 천간의 십성을 읽고, 4~15장에서 십이신살 각각의 유무와 위치를 확인하세요. 16~18장은 쌍 관계와 그룹 관계를 연결해서 보여주고, 19장은 대운과 세운의 글자를 설명합니다. 마지막 장에서는 지장간과 운의 지지 대조를 보충합니다. 긴 설명에서 필요한 항목으로 바로 이동할 수 있도록 목차를 제공합니다.',
    '신살의 유무는 적용한 규칙에 따른 계산이고, 설명에 나오는 태도와 질문은 그 상징을 생활에 연결하기 위한 제안입니다. 계산 결과와 실제 경험을 비교할 때는 맞는 사례뿐 아니라 맞지 않는 사례도 함께 남겨보세요. 한 이름에 모든 경험을 연결하는 대신 어떤 조건에서 도움이 되는 관점인지 살펴보는 편이 좋습니다.')+
   section('현재 결과에서 확인할 범위',
    input.unknown?'현재는 시주를 제외한 세 기둥의 결과입니다. 따라서 신살의 미해당과 지지 관계의 부재는 알려진 세 기둥에 한정됩니다. 정오를 가정한 대운 시작도 추정치이며, 출생 시간 확인 후 다시 계산하면 표시 위치와 일부 관계가 달라질 수 있습니다. 확인되지 않은 시주를 임의로 채워 성격이나 미래를 설명하지 않았습니다.':'출생 시각과 경도 보정 설정이 시주나 날짜 경계에 가까우면 원국 글자가 달라질 수 있습니다. 입력한 생일·시간·출생지와 실제 기록을 먼저 비교하세요. 글자의 관계를 많이 보여주더라도 모든 명리 규칙을 종합한 판정은 아니며, 강약·용신·격국의 확정 판단은 이 리포트에 포함되지 않습니다.')+
   section('직접 확인할 판정 자료',
    '십이신살의 순서와 삼합 그룹별 대상표는 <a href="https://doc.8-codes.com/ja/docs/lecture/19/" target="_blank" rel="noopener">丁亥 만세력의 십이신살 표</a>를 대조했습니다. 년지·일지 기준은 분리하여 표시합니다. 형·파·해 규칙과 두 글자 형의 표시 방식은 <a href="https://clarifyhk.com/zh-hans/learn/bazi/earthly-branches/reading-order-for-punishments-harms-and-breaks" target="_blank" rel="noopener">Clarify의 지지 관계 설명</a>에서 비교할 수 있습니다. 링크는 판정 규칙을 확인하기 위한 자료이며, 미래 사건을 입증하는 근거는 아닙니다.'));
 }
 window.OngyeolReportDetails={twelvePages,relationships,concluding,topics};
})();
